                [0, 0, 0]
            ];
            var grid = new Grid(matrix);
            var coords = neighborCoords(grid, 1, 1);
            var hasUR = coords.some(function(c) { return c[0] === 2 && c[1] === 0; });
            hasUR.should.be.false('expected ↗ excluded when both s0 and s1 are blocked');
