        // d2 = s1||s2 → ↘ (2,2)
        it('d2 (↘): included when only down (s2) is walkable and right (s1) is blocked', function() {
            var matrix = [
                [0, 0, 0],
                [0, 0, 1],  // (2,1) blocked → s1=false
