            var nodeOmitted = new PF.Node(0, 0);
            var nodeExplicit = new PF.Node(0, 0, undefined);
            nodeExplicit.walkable.should.equal(nodeOmitted.walkable);
            nodeExplicit.walkable.should.equal(true);
        });
    });
});

